package com.example.examplemod.gameplay;

import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.level.saveddata.SavedData;

public class SavedDataMyst extends SavedData {
    private int chargeLevel;

    public SavedDataMyst() {
    }

    public static SavedDataMyst get(MinecraftServer server) {
        return server.overworld().getDataStorage().computeIfAbsent(
                SavedDataMyst::new, SavedDataMyst::new, "examplemod_myst");
    }

    public int getChargeLevel() {
        return chargeLevel;
    }

    public void setChargeLevel(int v) {
        this.chargeLevel = Math.max(0, v);
        setDirty();
    }

    @Override
    public CompoundTag save(CompoundTag tag, HolderLookup.Provider registries) {
        tag.putInt("charge", chargeLevel);
        return tag;
    }

    public static SavedDataMyst load(CompoundTag tag, HolderLookup.Provider p) {
        SavedDataMyst d = new SavedDataMyst();
        d.chargeLevel = Math.max(0, tag.getInt("charge"));
        return d;
    }
}

