public class StaleSaveUpgrade {
    // 0->0, 50->half, 100->max; values >100 are already in new scale
    public static int migrateCharge(int oldRawValue, int newMaxCharge) {
        if (oldRawValue <= 0) return 0;
        if (oldRawValue > 100) return Math.min(oldRawValue, newMaxCharge);
        return oldRawValue * newMaxCharge / 100;
    }
}

