    // unload may race with ticking; concurrent map keeps this safe
    private static final Map<String, Integer> store = new ConcurrentHashMap<>();

    public static void onUnload(String worldKey, BlockPos pos, int charge) {
        store.put(worldKey + ":" + pos.asLong(), charge);
