public class StructurePlacementRule {
    // vanilla semantics: one structure candidate per spacing-grid cell,
    // offset jitter bounded by separation
    public static boolean spawnsHere(int chunkX, int chunkZ, long seed,
                                     int spacing, int separation) {
        int rx = Math.floorDiv(chunkX, Math.max(1, spacing));
        int rz = Math.floorDiv(chunkZ, Math.max(1, spacing));
        long h = Math.abs(Long.hashCode(
                seed ^ rx * 341873128712L ^ rz * 132897987541L));
        int offX = (int) (h % Math.max(1, spacing - separation));
        int offZ = (int) ((h / 7) % Math.max(1, spacing - separation));
        return (chunkX - rx * spacing) == offX
                && (chunkZ - rz * spacing) == offZ;
    }
}

