import java.util.concurrent.ConcurrentLinkedQueue;

public class ThreadSafeQueue {
    // network handlers run OFF the main thread: shared state must be
    // concurrent or queued for main-thread consumption
    private final ConcurrentLinkedQueue<Long> backing =
            new ConcurrentLinkedQueue<>();

    public void add(long value) {
        backing.add(value);
    }

    public ArrayList<Long> drainAll() {
        ArrayList<Long> out = new ArrayList<>();
        Long v;
        while ((v = backing.poll()) != null) {
            out.add(v);
        }
        return out;
    }
}

