        if (values == null || values.isEmpty()) return 0;
        int cap = Math.max(1, maxPerBatch);
        return (values.size() + cap - 1) / cap;
    }
}

package com.example.examplemod.network;

import java.util.Set;

public class RegistrationAudit {
    // payload TYPE ResourceLocations are globally unique per mod:
    // duplicates break dispatch
    public static String audit(Set<String> seenTypes, String type) {
        return seenTypes.add(type) ? "ok" : "duplicate_type";
    }
}

package com.example.examplemod.network;

public class EncryptionBoundary {
    // payloads are not end-to-end encrypted: never place secrets in them
    public static boolean containsSecret(String payloadText) {
        return payloadText != null
                && (payloadText.contains("token")
                    || payloadText.contains("password"));
    }

    public static String redact(String s) {
        return containsSecret(s) ? "[redacted]" : s;
    }
}

