public class SidedClassLoadingDoc {
    public static String strategyFor(String className, boolean guarded) {
        boolean client = className != null
                && className.startsWith("net.minecraft.client.");
        if (!client) return "universal";
        return guarded ? "client_safe" : "server_crash_risk";
    }
